package com.neml.badminton.service;
import com.fasterxml.jackson.databind.ObjectMapper;import com.neml.badminton.dto.AdministrativeConfigurationDtos.*;import com.neml.badminton.entity.*;import com.neml.badminton.repository.*;import jakarta.transaction.Transactional;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import java.time.Instant;import java.util.*;
@Service public class AdministrativeConfigurationService{
 private final ChampionshipRepository championships;private final ChampionshipBrandingConfigurationRepository branding;private final AuctionConfigurationRepository auctions;private final AuctionRepository operationalAuctions;private final TournamentSettingsRepository settings;private final TeamRepository teams;private final CompetitionConfigurationRepository competition;private final CompetitionAuditEventRepository audit;private final ConfigurationSectionService sections;private final ObjectMapper json;private final AuctionPolicyGuard policyGuard;private final PlayerRepository players;
 public AdministrativeConfigurationService(ChampionshipRepository championships,ChampionshipBrandingConfigurationRepository branding,AuctionConfigurationRepository auctions,AuctionRepository operationalAuctions,TournamentSettingsRepository settings,TeamRepository teams,CompetitionConfigurationRepository competition,CompetitionAuditEventRepository audit,ConfigurationSectionService sections,ObjectMapper json,AuctionPolicyGuard policyGuard,PlayerRepository players){this.championships=championships;this.branding=branding;this.auctions=auctions;this.operationalAuctions=operationalAuctions;this.settings=settings;this.teams=teams;this.competition=competition;this.audit=audit;this.sections=sections;this.json=json;this.policyGuard=policyGuard;this.players=players;}
 public BrandingDto branding(UUID cid){championship(cid);return dto(branding.findFirstByChampionshipIdOrderByConfigurationVersionDesc(cid).orElseThrow(()->missing("Branding configuration")));}
 @Transactional public BrandingDto updateBranding(UUID cid,BrandingRequest r,User actor){Championship c=championship(cid);ChampionshipBrandingConfiguration old=branding.findLatestForUpdate(cid).orElseThrow(()->missing("Branding configuration"));version(old.getConfigurationVersion(),r.expectedVersion());old.setStatus(ConfigurationStatus.SUPERSEDED);branding.save(old);ChampionshipBrandingConfiguration next=ChampionshipBrandingConfiguration.builder().championship(c).configurationVersion(old.getConfigurationVersion()+1).status(ConfigurationStatus.VALID).displayName(r.displayName().trim()).shortName(r.shortName().trim()).logoReference(trim(r.logoReference())).primaryColor(r.primaryColor()).secondaryColor(r.secondaryColor()).sponsorName(trim(r.sponsorName())).sponsorLogoReference(trim(r.sponsorLogoReference())).publicDescription(trim(r.publicDescription())).contactInformation(trim(r.contactInformation())).publicVisibility(r.publicVisibility()).build();branding.save(next);c.setIsPublic(r.publicVisibility());championships.save(c);sections.markValid(cid,"BRANDING",actor,List.of());record(c,actor,"BRANDING_CONFIGURATION_CHANGED",next.getConfigurationVersion(),Map.of("beforeVersion",old.getConfigurationVersion(),"after",dto(next)));return dto(next);}
 public AuctionConfigDto auction(UUID cid){championship(cid);return dto(auctions.findFirstByChampionshipIdOrderByConfigurationVersionDesc(cid).orElseThrow(()->missing("Auction configuration")));}
 @Transactional public AuctionConfigDto updateAuction(UUID cid,AuctionConfigRequest r,User actor){Championship c=policyGuard.lockEditable(cid);AuctionConfiguration old=auctions.findLatestForUpdate(cid).orElseThrow(()->missing("Auction configuration"));version(old.getConfigurationVersion(),r.expectedVersion());if(operationalAuctions.findAllByChampionshipIdOrderByCreatedAtDesc(cid).stream().anyMatch(a->a.getStatus()!=AuctionStatus.NOT_STARTED))conflict("Auction policy is locked after the first auction action");List<String> errors=new ArrayList<>();if(r.maximumBid()!=null&&players.findAllByChampionshipIdOrderByAuctionOrderAsc(cid).stream().anyMatch(p->p.getAuction()!=null&&p.getBasePrice().compareTo(r.maximumBid())>0))errors.add("An existing player base price exceeds the maximum bid");if(r.maximumBid()!=null&&r.maximumBid().compareTo(r.minimumBid())<0)errors.add("Maximum bid must be at least the minimum bid");if(r.maximumPremiumPurchases()!=null&&r.maximumBid()==null)errors.add("Premium purchase limit requires a maximum bid");if(r.minimumRosterSize()>r.maximumRosterSize())errors.add("Minimum roster size cannot exceed maximum roster size");if(r.maximumRetainedPlayers()>r.maximumRosterSize())errors.add("Retained-player limit cannot exceed maximum roster size");CompetitionConfiguration cc=competition.findByChampionshipId(cid).orElseThrow(()->missing("Competition configuration"));if(r.minimumRosterSize()!=cc.getMinimumRosterSize()||r.maximumRosterSize()!=cc.getMaximumRosterSize())errors.add("Auction roster limits must match championship roster limits");if(!errors.isEmpty())bad(String.join("; ",errors));old.setStatus(ConfigurationStatus.SUPERSEDED);auctions.save(old);AuctionConfiguration next=AuctionConfiguration.builder().championship(c).configurationVersion(old.getConfigurationVersion()+1).status(ConfigurationStatus.VALID).enabled(r.enabled()).auctionType(r.auctionType()).teamBudget(r.teamBudget()).minimumBid(r.minimumBid()).bidIncrement(r.bidIncrement()).minimumRosterSize(r.minimumRosterSize()).maximumRosterSize(r.maximumRosterSize()).retainedPlayersAllowed(r.retainedPlayersAllowed()).maximumRetainedPlayers(r.maximumRetainedPlayers()).unsoldPlayerReauctionAllowed(r.unsoldPlayerReauctionAllowed()).purseCarryForwardPolicy(r.purseCarryForwardPolicy()).auctionOrderPolicy(r.auctionOrderPolicy()).timerSeconds(r.timerSeconds()).maximumBid(r.maximumBid()).maximumPremiumPurchases(r.maximumPremiumPurchases()).captainPreassignmentRequired(r.captainPreassignmentRequired()).build();auctions.save(next);TournamentSettings legacy=settings.findByChampionshipId(cid).orElseThrow(()->missing("Tournament settings"));legacy.setPurseLimit(r.teamBudget());legacy.setPlayerBasePrice(r.minimumBid());legacy.setBidIncrement(r.bidIncrement());legacy.setMaxSquadSize(r.maximumRosterSize());legacy.setTimerSeconds(r.timerSeconds());settings.save(legacy);List<Team> configuredTeams=teams.findAllByChampionshipIdOrderByName(cid);for(Team team:configuredTeams){team.setPurseTotal(r.teamBudget());team.setPurseRemaining(r.teamBudget());}teams.saveAll(configuredTeams);sections.markValid(cid,"AUCTION",actor,List.of());record(c,actor,"AUCTION_CONFIGURATION_CHANGED",next.getConfigurationVersion(),Map.of("beforeVersion",old.getConfigurationVersion(),"after",dto(next)));return dto(next);}
 private BrandingDto dto(ChampionshipBrandingConfiguration c){return new BrandingDto(c.getConfigurationVersion(),c.getStatus(),c.getDisplayName(),c.getShortName(),c.getLogoReference(),c.getPrimaryColor(),c.getSecondaryColor(),c.getSponsorName(),c.getSponsorLogoReference(),c.getPublicDescription(),c.getContactInformation(),c.getPublicVisibility());}private AuctionConfigDto dto(AuctionConfiguration c){return new AuctionConfigDto(c.getConfigurationVersion(),c.getStatus(),c.getEnabled(),c.getAuctionType(),c.getTeamBudget(),c.getMinimumBid(),c.getBidIncrement(),c.getMinimumRosterSize(),c.getMaximumRosterSize(),c.getRetainedPlayersAllowed(),c.getMaximumRetainedPlayers(),c.getUnsoldPlayerReauctionAllowed(),c.getPurseCarryForwardPolicy(),c.getAuctionOrderPolicy(),c.getTimerSeconds(),c.getMaximumBid(),c.getMaximumPremiumPurchases(),c.getCaptainPreassignmentRequired());}
 private void record(Championship c,User actor,String type,int version,Object payload){try{audit.save(CompetitionAuditEvent.builder().championship(c).actor(actor).eventType(type).revision(version).configurationVersion(version).entityType("CHAMPIONSHIP").entityId(c.getId()).correlationId(UUID.randomUUID()).payload(json.writeValueAsString(payload)).occurredAt(Instant.now()).build());}catch(Exception e){throw new IllegalStateException("Unable to audit configuration",e);}}private Championship championship(UUID cid){return championships.findById(cid).orElseThrow(()->missing("Championship"));}private void version(int current,int expected){if(current!=expected)conflict("Configuration version conflict: reload before saving");}private String trim(String value){return value==null||value.isBlank()?null:value.trim();}private void bad(String m){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}private void conflict(String m){throw new ResponseStatusException(HttpStatus.CONFLICT,m);}private ResponseStatusException missing(String v){return new ResponseStatusException(HttpStatus.NOT_FOUND,v+" not found");}
}
